def get_diag_neighbors(grid, r, c):
    rows, cols = len(grid), len(grid[0])
    diags = []
    if r > 0 and c > 0 and grid[r-1][c-1] == grid[r][c]: diags.append((r-1,c-1))
    if r > 0 and c < cols-1 and grid[r-1][c+1] == grid[r][c]: diags.append((r-1,c+1))
    if r < rows-1 and c > 0 and grid[r+1][c-1] == grid[r][c]: diags.append((r+1,c-1))
    if r < rows-1 and c < cols-1 and grid[r+1][c+1] == grid[r][c]: diags.append((r+1,c+1))
    return diags

